"use client";

import { loadFont } from "@remotion/google-fonts/Geologica";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  interpolateColors,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_LABEL,
  DEFAULT_NAME,
  DEFAULT_STEPS,
  splitWords,
  stepsOf,
  type WhichMeansElementId,
  whichMeansTimeline,
} from "./timeline";

const geologica = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface WhichMeansProps {
  name?: string;
  label?: string;
  steps?: string[];
  hinge?: string;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy. Load it yourself; Geologica by default. */
  fontFamily?: string;
  /** Frames between words as a step is written. */
  stagger?: number;
  /** Frames the last step holds before the end. */
  hold?: number;
  /** Size of the text, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the name, the label and each step, by the ids
   * in `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<WhichMeansElementId>;
}

const THEMES = {
  dark: { bg: "#0E3B43", ink: "#FFFFFF", accent: "#4FE3D0" },
  light: { bg: "#E8F6F5", ink: "#0B3138", accent: "#0F8C7E" },
} as const;

const FONT_PX = 200;
const NAME_W = 500;
const BODY_W = 400;
const NAME_TRACK = -0.035;
const BODY_TRACK = -0.02;
const LH = 1.16;
const NAME_LH = 1.02;
const HINGE_EM = 0.5;
const GAP_EM = 0.5;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_MOVE = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const DIM = 0.5;

type Metrics = Record<string, number>;
const key = (w: number, s: string) => `${w}\u0002${s}`;

function measureAll(texts: string[], fontFamily: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("which-means: no 2d context");
  const out: Metrics = {};
  for (const weight of [NAME_W, BODY_W]) {
    ctx.font = `${weight} ${FONT_PX}px "${fontFamily}"`;
    for (const s of texts) {
      out[key(weight, s)] = ctx.measureText(s).width / FONT_PX;
    }
  }
  return out;
}

function useMetrics(texts: string[], fontFamily: string) {
  const id = `${fontFamily}\u0003${texts.join("\u0001")}`;
  const [state, setState] = useState<{ id: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("which-means: measuring"));
  const released = useRef(false);
  const input = useRef(texts);
  input.current = texts;
  useEffect(() => {
    let live = true;
    Promise.all([
      geologica.waitUntilDone(),
      document.fonts.load(`${NAME_W} 100px "${fontFamily}"`),
      document.fonts.load(`${BODY_W} 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ id, m: measureAll(input.current, fontFamily) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [id, handle, fontFamily]);
  return state && state.id === id ? state.m : null;
}

function greedy(
  words: string[],
  width: (w: string) => number,
  space: number,
  limit: number,
) {
  const lines: string[][] = [];
  let cur: string[] = [];
  let acc = 0;
  for (const w of words) {
    const ww = width(w);
    if (cur.length > 0 && acc + space + ww > limit) {
      lines.push(cur);
      cur = [w];
      acc = ww;
    } else {
      acc = cur.length > 0 ? acc + space + ww : ww;
      cur.push(w);
    }
  }
  if (cur.length > 0) lines.push(cur);
  return lines;
}

function balanced(
  words: string[],
  width: (w: string) => number,
  space: number,
  limit: number,
) {
  const count = greedy(words, width, space, limit).length;
  let lo = 0;
  let hi = limit;
  for (let i = 0; i < 18; i++) {
    const mid = (lo + hi) / 2;
    if (greedy(words, width, space, mid).length <= count) hi = mid;
    else lo = mid;
  }
  return greedy(words, width, space, hi);
}

function partitions(words: string[], parts: number): string[][][] {
  if (parts <= 1 || words.length <= 1) return [[words]];
  const out: string[][][] = [];
  for (let cut = 1; cut <= words.length - parts + 1; cut++) {
    for (const rest of partitions(words.slice(cut), parts - 1)) {
      out.push([words.slice(0, cut), ...rest]);
    }
  }
  return out;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

interface Clause {
  lines: string[][];
  h: number;
}

export function WhichMeans(props: WhichMeansProps) {
  const {
    name = DEFAULT_NAME,
    label = DEFAULT_LABEL,
    steps = DEFAULT_STEPS,
    hinge = "which means",
    accent,
    ink,
    background,
    fontFamily = geologica.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  // The steps spread over the clip after `delay`, as before.
  const tl = useTimeline(
    whichMeansTimeline,
    props,
    Math.max(0, durationInFrames - delay) * speed,
    timing,
  );
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const list = stepsOf(steps);
  const nameWords = splitWords(name);
  const m = useMetrics(
    [" ", "…", ...nameWords, ...list.flatMap(splitWords), hinge, label],
    fontFamily,
  );

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = list.length;
  const portrait = H > W * 1.1;
  const marginX = W * (portrait ? 0.08 : 0.07);

  const nameX = marginX;
  const colX = portrait ? marginX : W * 0.36;
  const nameMaxW = portrait ? W - marginX * 2 : colX - marginX - W * 0.055;
  const colW = W - marginX - colX;

  const nW = (s: string) =>
    m[key(NAME_W, s)] + NAME_TRACK * Array.from(s).length;
  const bW = (s: string) =>
    m[key(BODY_W, s)] + BODY_TRACK * Array.from(s).length;
  const nSpace = nW(" ");
  const bSpace = bW(" ");
  const lineWidth = (line: string[], f: (s: string) => number, sp: number) =>
    line.reduce((a, w, i) => a + f(w) + (i > 0 ? sp : 0), 0);

  const nameCap = H * (portrait ? 0.09 : 0.16);
  let nameLines: string[][] = [nameWords];
  let nameF = 0;
  let nameScore = -1;
  for (let L = 1; L <= Math.min(3, nameWords.length); L++) {
    for (const p of partitions(nameWords, L)) {
      const wEm = Math.max(...p.map((l) => lineWidth(l, nW, nSpace)));
      const f = Math.min(nameCap, nameMaxW / wEm);
      const score = f / (1 + 0.12 * (L - 1));
      if (score > nameScore) {
        nameScore = score;
        nameF = f;
        nameLines = p;
      }
    }
  }

  const bodyCap = H * (portrait ? 0.058 : 0.1);
  const maxStack = H * (portrait ? 0.56 : 0.86);
  let F = bodyCap;
  let clauses: Clause[] = [];
  for (let i = 0; i < 40; i++) {
    clauses = list.map((s) => {
      const lines = balanced(splitWords(s), bW, bSpace, colW / F);
      return { lines, h: lines.length * LH * F };
    });
    const tallest = Math.max(...clauses.map((cl) => cl.h));
    const stack = tallest * 2 + F * (HINGE_EM + GAP_EM * 2);
    const tooMany = clauses.some((cl) => cl.lines.length > 3);
    if (!tooMany && stack <= maxStack) break;
    F *= 0.95;
  }

  const stepEls = list.map((_, k) => tl.get(`step:${k}`));

  const easeAt = (tt: number, from: number, dur: number, curve = EASE_OUT) =>
    interpolate(tt, [from, from + dur], [0, 1], { ...CLAMP, easing: curve });
  const ease = (from: number, dur: number, curve = EASE_OUT) =>
    easeAt(t, from, dur, curve);
  // A move counts while its offset in px changes against either neighbouring
  // frame by more than a thousandth of a pixel: the eases' tails still cross
  // pixels after their progress is all but settled.
  const stirs = (at: (tt: number) => number) => {
    const now = at(t);
    return (
      Math.abs(at(t + speed) - now) > 1e-3 ||
      Math.abs(now - at(t - speed)) > 1e-3
    );
  };

  const hingeY = portrait ? H * 0.57 : H * 0.5;
  const hingeF = F * HINGE_EM;
  const gap = F * GAP_EM;
  const causeBottom = hingeY - hingeF / 2 - gap;
  const effectTop = hingeY + hingeF / 2 + gap;
  const causeTop = (k: number) => causeBottom - clauses[k].h;

  const nameH = nameLines.length * NAME_LH * nameF;
  const labelF = Math.max(12, nameF * 0.3, F * 0.46);
  const nameTop = portrait ? H * 0.16 : hingeY - nameH / 2 + labelF * 0.6;

  const nodes: React.ReactNode[] = [];

  if (label) {
    const labelEl = tl.get("label");
    const labelIn = ease(labelEl.start, labelEl.length);
    nodes.push(
      <div
        key="label"
        style={{
          position: "absolute",
          left: nameX,
          top: nameTop - labelF * 1.9,
          fontFamily,
          fontWeight: BODY_W,
          fontSize: labelF,
          lineHeight: 1,
          color: hi,
          opacity: labelIn,
          transform: `translateY(${((1 - labelIn) * labelF * 0.6).toFixed(2)}px)${glide(
            stirs(
              (tt) => easeAt(tt, labelEl.start, labelEl.length) * labelF * 0.6,
            ),
          )}`,
          whiteSpace: "pre",
        }}
      >
        {label}
      </div>,
    );
  }

  const nameEl = tl.get("name");
  nameLines.forEach((line, li) => {
    nodes.push(
      <div
        key={`name-${line.join(" ")}`}
        style={{
          position: "absolute",
          left: nameX - nameF * 0.04,
          top: nameTop + li * NAME_LH * nameF - nameF * 0.08,
          height: nameF * NAME_LH + nameF * 0.16,
          paddingLeft: nameF * 0.04,
          paddingRight: nameF * 0.1,
          overflow: "hidden",
          fontFamily,
          fontWeight: NAME_W,
          fontSize: nameF,
          lineHeight: `${nameF * NAME_LH + nameF * 0.16}px`,
          letterSpacing: `${NAME_TRACK}em`,
          color: fg,
          whiteSpace: "pre",
        }}
      >
        {line.map((w, wi) => {
          const at = nameEl.start + (li * 2 + wi) * nameEl.beat("step");
          const e = ease(at, nameEl.beat("rise"));
          return (
            <span
              key={w}
              style={{
                display: "inline-block",
                transform: `translateY(${((1 - e) * nameF * 1.1).toFixed(2)}px)${glide(
                  stirs(
                    (tt) => easeAt(tt, at, nameEl.beat("rise")) * nameF * 1.1,
                  ),
                )}`,
              }}
            >
              {wi > 0 ? ` ${w}` : w}
            </span>
          );
        })}
      </div>,
    );
  });

  const renderClause = (
    k: number,
    top: number,
    lift: (tt: number) => number,
    opacity: number,
    color: string,
    writeAt: number,
    endDot: number,
    ellipsis: number,
  ) => {
    const cl = clauses[k];
    const stepEl = stepEls[k];
    const wordStep = stepEl.beat("stagger");
    const wordIn = stepEl.beat("wordIn");
    const last = k === n - 1;
    let wordIndex = 0;
    const dy = lift(t);
    const moving = stirs(lift);
    return (
      <div
        key={`clause-${k}`}
        style={{
          position: "absolute",
          left: colX,
          top,
          transform: `translateY(${Math.abs(dy) < 1e-3 ? 0 : dy}px)${glide(moving)}`,
          width: colW + F,
          opacity,
          color,
          fontFamily,
          fontWeight: BODY_W,
          fontSize: F,
          letterSpacing: `${BODY_TRACK}em`,
          lineHeight: `${LH * F}px`,
          whiteSpace: "pre",
        }}
      >
        {ellipsis > 0 && colX > (bW("…") + 0.12) * F ? (
          <span
            style={{
              position: "absolute",
              left: -bW("…") * F - F * 0.06,
              top: 0,
              opacity: ellipsis,
            }}
          >
            …
          </span>
        ) : null}
        {cl.lines.map((line, li) => (
          <div key={line.join(" ")}>
            {line.map((w, wi) => {
              const at = writeAt + wordIndex++ * wordStep;
              const e = ease(at, wordIn);
              const isEnd =
                li === cl.lines.length - 1 && wi === line.length - 1;
              return (
                <span
                  key={`${w}-${wi}`}
                  style={{
                    display: "inline-block",
                    opacity: e,
                    transform: `translateY(${((1 - e) * F * 0.45).toFixed(2)}px)${glide(
                      !moving &&
                        stirs((tt) => easeAt(tt, at, wordIn) * F * 0.45),
                    )}`,
                  }}
                >
                  {wi > 0 ? ` ${w}` : w}
                  {isEnd ? (
                    <span style={{ position: "relative" }}>
                      <span style={{ opacity: last ? 1 : endDot }}>.</span>
                      {last ? null : (
                        <span
                          style={{
                            position: "absolute",
                            left: 0,
                            top: 0,
                            opacity: 1 - endDot,
                          }}
                        >
                          ,
                        </span>
                      )}
                    </span>
                  ) : null}
                </span>
              );
            })}
          </div>
        ))}
      </div>
    );
  };

  const step1 = n > 1 ? stepEls[1] : null;
  // A lone step still dims where the second would have come.
  const s1 = step1 ? step1.start : stepEls[0].start + stepEls[0].beat("read");
  const dimmer = step1 ?? stepEls[0];
  const c0SlotAt = (tt: number) =>
    step1 ? easeAt(tt, s1, step1.beat("slot"), EASE_MOVE) : 0;

  for (let k = 0; k < n; k++) {
    const stepEl = stepEls[k];
    const enter = stepEl.start;
    if (t < enter - 1) continue;
    const promoting = k >= 1 && k + 1 < n;
    const isLast = k === n - 1;

    // Each clause is laid out where its last move lands and travels by a
    // transform all its life: layout rounds a baseline to whole pixels, so a
    // clause eased by `top` clicks up pixel by pixel, and one handed back to
    // layout jumps.
    let top: number;
    let from = (_tt: number) => 0;
    let opacity = 1;
    let writeAt: number;
    let endDot = 1;
    let ellipsis = 0;

    if (k === 0) {
      writeAt = enter;
      const centred = hingeY - clauses[0].h / 2;
      const slotted = causeTop(0);
      top = n > 1 ? slotted : centred;
      if (n > 1) from = (tt) => (centred - slotted) * (1 - c0SlotAt(tt));
      opacity =
        1 - (1 - DIM) * ease(s1 + dimmer.beat("dimAt"), dimmer.beat("dim"));
      endDot = step1
        ? 1 - ease(s1 + step1.beat("dotAt"), step1.beat("dotOut"))
        : 1;
    } else {
      writeAt = enter + stepEl.beat("write");
      top = effectTop;
      if (promoting) {
        const next = stepEls[k + 1];
        const promoteAt = next.start;
        const push = next.beat("push");
        const riseAt = (tt: number) => easeAt(tt, promoteAt, push, EASE_MOVE);
        const slotted = causeTop(k);
        top = slotted;
        from = (tt) => (effectTop - slotted) * (1 - riseAt(tt));
        opacity =
          1 -
          (1 - DIM) * ease(promoteAt + next.beat("dimAt"), next.beat("dim"));
        endDot = 1 - ease(promoteAt + next.beat("dotAt"), next.beat("dotOut"));
        ellipsis = ease(
          promoteAt + push + next.beat("ellipsisAt"),
          next.beat("ellipsisIn"),
        );
      }
    }

    let lift = from;
    if (k + 2 < n) {
      const leave = stepEls[k + 2];
      const leaveAt = leave.start;
      const exitLen = leave.beat("exit");
      const exit = ease(leaveAt, exitLen, EASE_MOVE);
      if (exit >= 1) continue;
      const travel = from;
      lift = (tt) =>
        travel(tt) - easeAt(tt, leaveAt, exitLen, EASE_MOVE) * F * 0.9;
      opacity *= 1 - exit;
    }

    const color = isLast
      ? interpolateColors(
          ease(
            enter + stepEl.beat("glowAt") + stepEl.beat("glow"),
            stepEl.beat("glowIn"),
          ),
          [0, 1],
          [fg, hi],
        )
      : fg;

    nodes.push(
      renderClause(k, top, lift, opacity, color, writeAt, endDot, ellipsis),
    );
  }

  if (step1) {
    const hingeIn = ease(s1, step1.beat("hingeIn"));
    let hingeOp = hingeIn;
    for (let k = 2; k < n; k++) {
      const e = stepEls[k];
      const p = e.start;
      const push = e.beat("push");
      const dip =
        interpolate(t, [p, p + e.beat("dip")], [0, 1], CLAMP) *
        (1 -
          interpolate(
            t,
            [p + push + e.beat("hingeBack"), p + push + e.beat("hingeBackEnd")],
            [0, 1],
            CLAMP,
          ));
      hingeOp *= 1 - dip;
    }
    nodes.push(
      <div
        key="hinge"
        style={{
          position: "absolute",
          left: colX,
          top: hingeY - hingeF * 0.6,
          fontFamily,
          fontWeight: BODY_W,
          fontSize: hingeF,
          lineHeight: `${hingeF * 1.2}px`,
          color: hi,
          opacity: hingeOp,
          transform: `translateX(${((1 - hingeIn) * -F * 0.4).toFixed(2)}px)`,
          whiteSpace: "pre",
        }}
      >
        {hinge}
      </div>,
    );
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>{nodes}</ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The label and the name rise in, the first step is written beside them, and
// each next step is written under the hinge while the one before rises into
// the cause slot and the one before that leaves. Frames on the 30 fps scene
// timeline, after `delay` and `speed`; the steps after the second spread over
// the clip. The ids are public: a saved `timing` prop refers to them.

export type WhichMeansElementId = "name" | "label" | `step:${number}`;

export interface WhichMeansTimingProps {
  name?: string;
  label?: string;
  steps?: string[];
  stagger?: number;
  hold?: number;
}

export const DEFAULT_NAME = "Live preview";
export const DEFAULT_LABEL = "New";
export const DEFAULT_STEPS = [
  "Every edit shows up as you type,",
  "you catch the typo before you render,",
  "the first render is the one you ship.",
];

const NAME_AT = 0;
const NAME_STEP = 3;
const NAME_RISE = 16;
const LABEL_AT = 4;
const LABEL_IN = 14;
const FIRST_AT = 12;
const FIRST_READ = 36;
const WORD_STAGGER = 2;
const WORD_IN = 12;
const CENTER_TO_SLOT = 14;
const EXIT = 11;
const RISE = 18;
const WRITE_AFTER_RISE = 13;
const TAIL = 76;

export const splitWords = (s: string) => s.split(/\s+/).filter(Boolean);
export const stripEnd = (s: string) => s.replace(/[\s,.;:…]+$/u, "");

/** The steps shown, without their end punctuation. */
export function stepsOf(steps: string[]) {
  return (steps.length > 0 ? steps : DEFAULT_STEPS).map(stripEnd);
}

// `label` rises in. `name` rises word by word, `step` apart (the step counts
// two per line of the measured name), each over `rise`. `step:<k>` is step
// `k`: its words are written from `write`, `stagger` apart, each over
// `wordIn`; the last step lights up `glow` frames after `glowAt`, over
// `glowIn`. Each step also moves the steps before it: step 1 slots the first
// one into the cause over `slot`, step 2 on rises the one before over `push`,
// both dim it from `dimAt` over `dim` and turn its comma into a full stop from
// `dotAt` over `dotOut`, and an ellipsis fades in from `push + ellipsisAt`
// over `ellipsisIn`. Step 2 on sends the step two back out over `exit` and
// dips the hinge (in over `dip`, back from `push + hingeBack` to
// `push + hingeBackEnd`); step 1 brings the hinge in over `hingeIn`. The
// steps form a chain. A lone step still dims `read` frames in, where the
// second would have come.
export const whichMeansTimeline = defineTimeline<
  WhichMeansElementId,
  WhichMeansTimingProps
>(
  (
    {
      name = DEFAULT_NAME,
      label = DEFAULT_LABEL,
      steps = DEFAULT_STEPS,
      stagger = WORD_STAGGER,
      hold = TAIL,
    },
    { length: span },
  ) => {
    const list = stepsOf(steps);
    const n = list.length;
    const nameCount = splitWords(name).length;
    const fixed = FIRST_AT + FIRST_READ + hold;
    const period =
      n > 2
        ? Math.min(72, Math.max(44, (span - fixed - 10) / (n - 2)))
        : Math.max(44, span - fixed);
    const stepAt = (k: number) =>
      k <= 0 ? FIRST_AT : FIRST_AT + FIRST_READ + (k - 1) * period;

    const elements: TimelineElement<WhichMeansElementId>[] = [
      {
        id: "name",
        lane: "Name",
        label: name,
        start: NAME_AT,
        length: Math.max(0, nameCount - 1) * NAME_STEP + NAME_RISE,
        beats: { step: NAME_STEP, rise: NAME_RISE },
      },
    ];
    if (label) {
      elements.push({
        id: "label",
        lane: "Label",
        label,
        start: NAME_AT + LABEL_AT,
        length: LABEL_IN,
      });
    }
    list.forEach((step, k) => {
      const write = k === 0 ? 0 : k === 1 ? 4 : WRITE_AFTER_RISE;
      const words = splitWords(step).length;
      elements.push({
        id: `step:${k}`,
        lane: "Steps",
        label: step,
        start: stepAt(k),
        length:
          k + 1 < n
            ? stepAt(k + 1) - stepAt(k)
